def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter, deque

    background = Counter(x for row in grid for x in row).most_common(1)[0][0]
    seen = [[False] * w for _ in range(h)]
    major = [[None] * w for _ in range(h)]

    # Keep substantial same-color components as the underlying shapes.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            not seen[ny][nx] and grid[ny][nx] == color):
                        seen[ny][nx] = True
                        q.append((ny, nx))
            if len(comp) >= 4:
                for y, x in comp:
                    major[y][x] = color

    out = [[background] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if major[r][c] is not None:
                out[r][c] = major[r][c]
                continue

            orth = Counter()
            around = Counter()
            for dy in (-1, 0, 1):
                for dx in (-1, 0, 1):
                    if dy == 0 and dx == 0:
                        continue
                    y, x = r + dy, c + dx
                    if 0 <= y < h and 0 <= x < w and major[y][x] is not None:
                        color = major[y][x]
                        around[color] += 1
                        if abs(dy) + abs(dx) == 1:
                            orth[color] += 1

            if around:
                color, count = around.most_common(1)[0]
                if orth[color] >= 2 or count >= 3:
                    out[r][c] = color

    return out
